import { useCallback, useEffect } from 'react'
import {
  CHEVRON_UP_BLACK,
  CHEVRON_DOWN_BLACK,
  CHEVRON_UP_WHITE,
  CHEVRON_DOWN_WHITE,
} from '../../../../../../../images/imageUrl'
import LazyLoader from '../../../../../../../components/LazyLoader'
import useEventTracker from '../../../../../../../hooks/trackers'
import { useGetRenewalPolicyList, useSetPolicyState } from '../../../../state/hooks/usePolicyState'
import PolicyApplicationCard from '../../../TransactionList/container/components/PolicyApplicationCard'
import useRenewalAllocation from '../../hooks/useRenewalAllocation'
import EmptyTransactions from '../EmptyTransactions'
import { ListContainerStyle, SectionHeader } from './index.style'

function ListPolicyRenewal(props) {
  const { tab, searchText, getTransactionSummaryData, isOpen = false, setIsOpen = () => {} } = props

  const { redirectToRenewalAllocation } = useRenewalAllocation()
  const { trackUserEvent } = useEventTracker()

  const [{ getRenewalPolicyListData }, _getRenewalPolicyListRequest] = useGetRenewalPolicyList()
  const getRenewalPolicyListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 20,
        search: searchText,
        ...tab.filters,
        ...params,
      }
      _getRenewalPolicyListRequest(query)
    },
    [_getRenewalPolicyListRequest, tab, searchText]
  )

  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    if (isOpen) {
      getRenewalPolicyListRequest()
    }
    return () => {
      setPolicyState({ getRenewalPolicyListData: null })
    }
  }, [isOpen, getRenewalPolicyListRequest, setPolicyState])

  const handleToggleList = useCallback(() => {
    setIsOpen(!isOpen)
  }, [isOpen, setIsOpen])

  const handleClickPolicyCard = useCallback(
    (data) => {
      trackUserEvent('[MV Renewal] Renew Policy', {
        source: 'Renewal List Page',
        renewal_allocation: data?.attributes?.renewal_allocation,
        insurance_provider: data?.insurance_provider,
        vehicle_brand: data?.attributes?.object_insured?.brand_name,
        vehicle_model: data?.attributes?.object_insured?.model_name,
        vehicle_year: data?.attributes?.object_insured?.year,
        original_application_no: data?.application_no,
      })
      redirectToRenewalAllocation({
        referenceId: data?.reference_id,
        allocation: data?.attributes?.renewal_allocation,
      })
    },
    [redirectToRenewalAllocation, trackUserEvent]
  )

  return (
    <ListContainerStyle>
      <SectionHeader tabValue={tab?.value} onClick={handleToggleList}>
        <div className="left">
          <div className="title-container">
            <div className="title">{tab?.section?.title}</div>
            <div className="subtitle">{tab?.section?.subtitle}</div>
          </div>
        </div>
        <div className="right">
          <div className="text">
            {getTransactionSummaryData?.renewable_records?.[tab?.summary_count_key] || 0} Polis
          </div>
          <img
            className="chevron-black"
            src={isOpen ? CHEVRON_UP_BLACK : CHEVRON_DOWN_BLACK}
            alt=""
          />
          <img
            className="chevron-white"
            src={isOpen ? CHEVRON_UP_WHITE : CHEVRON_DOWN_WHITE}
            alt=""
          />
        </div>
      </SectionHeader>

      {isOpen &&
        (getRenewalPolicyListData?.data?.length > 0 ? (
          <div className="list-container">
            {getRenewalPolicyListData?.data.map((data, i) => (
              <PolicyApplicationCard
                key={i}
                type="RENEWAL"
                policyData={data}
                onClickCard={() => handleClickPolicyCard(data)}
              />
            ))}
            <LazyLoader
              pageSize={20}
              responseData={getRenewalPolicyListData}
              metaData={getRenewalPolicyListData?.meta_data}
              request={getRenewalPolicyListRequest}
              requestParams={{
                search: searchText,
                ...(tab?.filters || {}),
              }}
            />
          </div>
        ) : (
          <EmptyTransactions isSearch={!!searchText} />
        ))}
    </ListContainerStyle>
  )
}

export default ListPolicyRenewal
