import { useEffect, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { debounce } from 'lodash'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../../components'
import Tabs from '../../../../../../components/Tabs'
import { LANG_STRINGS } from '../../../../../../lang/index'
import {
  useGetRenewalPolicyList,
  useGetTransactionsSummary,
} from '../../../state/hooks/usePolicyState'
import ListPolicyRenewal from '../components/ListPolicyRenewal'
import { RENEWAL_TABS } from './constants'
import { RenewalListStyleWrapper, RenewalTabsWrapper } from './index.style'

function RenewalList() {
  const history = useHistory()

  const [searchText, setSearchText] = useState('')
  const [currentTab, setCurrentTab] = useState(RENEWAL_TABS[0])
  const [currentSection, setCurrentSection] = useState(RENEWAL_TABS[1].value)

  const [{ getRenewalPolicyListData }] = useGetRenewalPolicyList()
  const [{ getTransactionSummaryData = {} }, getTransactionSummaryReq] = useGetTransactionsSummary()
  const [{ GET_RENEWAL_POLICY_LIST_LOADER, GET_RENEWAL_ONE_TAP_DETAILS_LOADER }] =
    useLoaderContextValue()

  useEffect(() => {
    getTransactionSummaryReq()
  }, [getTransactionSummaryReq])

  const pageLoader =
    (GET_RENEWAL_POLICY_LIST_LOADER && !getRenewalPolicyListData?.length) ||
    GET_RENEWAL_ONE_TAP_DETAILS_LOADER

  return (
    <Container
      title={LANG_STRINGS.policyExtension}
      loader={pageLoader}
      showSearchBar
      onSearch={debounce(setSearchText, 500)}
      displayBackButton
      onBackClick={() => history.goBack()}
    >
      <RenewalListStyleWrapper>
        <RenewalTabsWrapper>
          <Tabs
            data={RENEWAL_TABS}
            defaultTab={RENEWAL_TABS[0]}
            onClick={(tab) => setCurrentTab(tab)}
          />
        </RenewalTabsWrapper>
        {currentTab.value === 'ALL' && (
          <>
            <ListPolicyRenewal
              tab={RENEWAL_TABS[1]} // BETWEEN_0_14
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
              isOpen={currentSection === RENEWAL_TABS[1].value}
              setIsOpen={() => setCurrentSection(RENEWAL_TABS[1].value)}
            />
            <ListPolicyRenewal
              tab={RENEWAL_TABS[2]} // BETWEEN_15_45
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
              isOpen={currentSection === RENEWAL_TABS[2].value}
              setIsOpen={() => setCurrentSection(RENEWAL_TABS[2].value)}
            />
            <ListPolicyRenewal
              tab={RENEWAL_TABS[3]} // EXPIRED
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
              isOpen={currentSection === RENEWAL_TABS[3].value}
              setIsOpen={() => setCurrentSection(RENEWAL_TABS[3].value)}
            />
          </>
        )}
        {currentTab.value !== 'ALL' && (
          <ListPolicyRenewal
            tab={currentTab}
            searchText={searchText}
            getTransactionSummaryData={getTransactionSummaryData}
            isOpen={true}
          />
        )}
      </RenewalListStyleWrapper>
    </Container>
  )
}

export default RenewalList
